 async function fetchTowers(force=false){const b=bounds(),c=center(),z=+map.getZoom();if(z<7.5){st.towers=[];return[]}if(c.lng<-180||c.lng>-60||c.lat<15||c.lat>72||Math.abs(b[2]-b[0])>22||Math.abs(b[3]-b[1])>14){st.towers=[];say('FCC source coverage is U.S.-focused. No RF locations inferred outside source bounds.');return[]}if(!force&&st.towers.length&&Date.now()-st.lastRfAt<12000)return st.towers;const [w,s,e,n]=[Math.max(-180,b[0]),Math.max(15,b[1]),Math.min(-60,b[2]),Math.min(72,b[3])];if(w>=e||s>=n)return[];const u=new URL(FCC_URL);Object.entries({where:'1=1',geometry:[w,s,e,n].join(','),geometryType:'esriGeometryEnvelope',inSR:4326,spatialRel:'esriSpatialRelIntersects',outFields:'OBJECTID,RegNum,Entity,Strucht,LocAdd,LocCity,LocState,ContName,ContState,FAAstudy',returnGeometry:true,outSR:4326,resultRecordCount:200,returnExceededLimitFeatures:true,f:'geojson'}).forEach(([k,v])=>u.searchParams.set(k,String(v)));const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),12000),seq=++st.rfFetchSeq;try{const r=await fetch(u,{headers:{Accept:'application/geo+json,application/json'},cache:'no-store',signal:ctl.signal});if(!r.ok)throw new Error('FCC source HTTP '+r.status);const d=await r.json();if(d.error)throw new Error(d.error.message||'FCC source query failed');if(!Array.isArray(d.features))throw new Error('FCC response did not contain features');if(seq!==st.rfFetchSeq)return st.towers;st.towers=d.features.map(f=>{const c=centroid(f),p=f.properties||{};if(!c||c.lng<-180||c.lng>180||c.lat<-90||c.lat>90)return null;return{lng:c.lng,lat:c.lat,id:String(p.RegNum??p.OBJECTID??''),owner:String(p.Entity??p.ContName??''),city:String(p.LocCity??''),state:String(p.LocState??''),distance:distanceM(center(),c)}}).filter(Boolean).sort((a,b)=>a.distance-b.distance).slice(0,60);st.lastRfAt=Date.now();return st.towers}catch(e){if(e.name!=='AbortError'){st.lastError=String(e.message||e);console.warn('BridgePoint RF data',e)}return st.towers}finally{clearTimeout(timer)}}
 async function rf(force=true){if(!st.rfOn)return;const seq=++st.rfDrawSeq;st.origin=center();const rows=await fetchTowers(force);if(seq!==st.rfDrawSeq||!st.rfOn)return;const layer=await ensureLayer();if(seq!==st.rfDrawSeq||!st.rfOn)return;clearGroup(layer.rfGroup);const THREE=st.three,r=st.rfMode==='5G'?450:900,sphere=new THREE.SphereGeometry(1,18,12),pin=new THREE.OctahedronGeometry(13,0),hue=st.rfMode==='5G'?'#b28aff':'#56d9ff',materials=[mat(THREE,hue,.055),mat(THREE,hue,.07),mat(THREE,hue,.26,true),mat(THREE,'#ffe0a0',.9)];st.towers=rows;for(const t of rows){const p=local(t.lng,t.lat,st.origin);[[1,materials[0],.52],[.68,materials[1],.4],[1,materials[2],.52]].forEach(([sc,m,v])=>{const mesh=new THREE.Mesh(sphere,m);mesh.position.set(p.x,r*v,p.z);mesh.scale.set(r*sc,r*v,r*sc);layer.rfGroup.add(mesh)});const marker=new THREE.Mesh(pin,materials[3]);marker.position.set(p.x,16,p.z);layer.rfGroup.add(marker)}layer.rfGroup.visible=true;layer.windGroup.visible=st.windOn;st.fieldAt=Date.now();$('[data-towers]').textContent=fmt(rows.length);say(rows.length?`RF planning envelopes: ${rows.length} FCC antenna structures · ${st.rfMode} nominal radius ${fmt(r)} m. These records do not confirm active cell radios and the radius is an assumption, not measured coverage.`:(st.lastError?'RF source unavailable: '+st.lastError:'No FCC structures returned for this viewport; no synthetic tower anchors placed.'));map.triggerRepaint?.()}

 function animate(){if(st.raf||document.hidden||(!st.windOn&&!st.droneOn))return;const frame=now=>{st.raf=0;if(document.hidden||(!st.windOn&&!st.droneOn))return;if(st.lastAnim&&now-st.lastAnim<32){st.raf=requestAnimationFrame(frame);return}const dt=st.lastAnim?clamp((now-st.lastAnim)/1000,0,.055):.016;st.lastAnim=now;if(st.windOn&&st.flowColorAttribute&&st.flowBaseColors&&st.flowProgress&&st.flowPhase){const arr=st.flowColorAttribute.array,base=st.flowBaseColors,progress=st.flowProgress,phase=st.flowPhase,t=now*.0016;for(let i=0;i<progress.length;i++){const pulse=.34+.66*Math.pow(.5+.5*Math.sin(progress[i]*Math.PI*2*7-t*2.6+phase[i]),2.2),j=i*3;arr[j]=base[j]*pulse;arr[j+1]=base[j+1]*pulse;arr[j+2]=base[j+2]*pulse}st.flowColorAttribute.needsUpdate=true}if(st.droneOn&&typeof updateDrone==='function')updateDrone(now,dt);map.triggerRepaint?.();st.raf=requestAnimationFrame(frame)};st.raf=requestAnimationFrame(frame)}
 function stop(){if(st.raf)cancelAnimationFrame(st.raf);st.raf=0;st.lastAnim=0}
 async function setWind(on){st.windOn=!!on;updateButtons();const l=await ensureLayer();if(!st.windOn){clearGroup(l.windGroup);st.voxels=0;st.flowLineCount=0;st.flowParticles=[];st.flowLines=[];st.flowColorAttribute=null;st.flowBaseColors=null;st.flowProgress=null;st.flowPhase=null;st.flowLineObject=null;st.windMeshes=[];l.windGroup.visible=false;if(!st.droneOn)restoreWindTerrain();if(!st.droneOn)stop();updateCounts();say(st.rfOn?'RF planning envelope remains visible.':st.droneOn?'Drone simulator remains active; wind lines are off.':'3D wind flow off.');map.triggerRepaint?.();return}l.windGroup.visible=true;await wind();updateCounts()}
 async function setRf(mode){const same=st.rfOn&&st.rfMode===mode;st.rfMode=mode;st.rfOn=!same;updateButtons();const l=await ensureLayer();if(!st.rfOn){clearGroup(l.rfGroup);l.rfGroup.visible=false;st.towers=[];updateCounts();say(st.windOn?'Wind voxel mesh remains visible.':'Volumetric fields off.');map.triggerRepaint?.();return}l.rfGroup.visible=true;await rf(true);updateCounts()}
 function updateCounts(){$('[data-voxels]').textContent=fmt(st.windOn?st.flowLineCount:0);$('[data-towers]').textContent=fmt(st.rfOn?st.towers.length:0)}
 function updateButtons(){const pairs=[['wind','DENSE WIND LINES',st.windOn],['rf4','RF 4G PLAN',st.rfOn&&st.rfMode==='4G'],['rf5','RF 5G PLAN',st.rfOn&&st.rfMode==='5G'],['drone','DRONE MODE',st.droneOn]];for(const [key,label,on] of pairs){root.querySelectorAll(`[data-action="${key}"]`).forEach(b=>{b.textContent=label+' · '+(on?'ON':'OFF');b.setAttribute('aria-pressed',String(on))})};root.querySelectorAll('[data-action="autopilot"]').forEach(b=>{b.textContent='AUTOPILOT · '+(st.droneAutopilot?'ON':st.droneRoute.length?'OFF':'PICK TARGET');b.disabled=!st.droneRoute.length})}
 async function refresh(force=true){const jobs=[];if(st.windOn)jobs.push(wind());if(st.rfOn)jobs.push(rf(force));if(!jobs.length){say('Choose wind, RF, or Drone Mode to materialize a field.');return}await Promise.allSettled(jobs);updateCounts()}
 function open(){root.hidden=false;const d=document.getElementById('bpv-dock');if(d)d.dataset.windDroneOpen='true';updateCounts();updateButtons();wireDroneControls()}function close(){root.hidden=true;const d=document.getElementById('bpv-dock');if(d)delete d.dataset.windDroneOpen}
 function mapMoved(){if(st.droneOn)return;clearTimeout(st.refreshTimer);st.refreshTimer=setTimeout(()=>void refresh(false),900)}
 $('[data-close]').addEventListener('click',close);$('[data-action="wind"]').addEventListener('click',()=>void setWind(!st.windOn).catch(e=>say('Wind field error: '+String(e.message||e))));$('[data-action="rf4"]').addEventListener('click',()=>void setRf('4G').catch(e=>say('RF field error: '+String(e.message||e))));$('[data-action="rf5"]').addEventListener('click',()=>void setRf('5G').catch(e=>say('RF field error: '+String(e.message||e))));$('[data-action="refresh"]').addEventListener('click',()=>void refresh(true));wireDroneControls();map.on?.('moveend',mapMoved);map.on?.('zoomend',mapMoved);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else if(st.windOn||st.droneOn)animate()});
 const api={version:VERSION,map,open,close,refresh,setWind,setRf,get state(){return{version:VERSION,windOn:st.windOn,rfOn:st.rfOn,rfMode:st.rfMode,windVoxels:st.voxels,windFlowLines:st.flowLineCount,windFlowSamples:st.voxels,terrainElevationActive:st.terrainAvailable,buildingObstacles:st.buildingObstacleCount,meshObstacleProxies:st.meshObstacleCount,towerAnchors:st.towers.length,windObservation:st.obs,droneOn:st.droneOn,droneAutopilot:st.droneAutopilot,dronePosition:st.dronePos,droneTarget:st.droneTarget,droneRouteWaypoints:st.droneRoute.length,droneVision:st.droneVision,updatedAt:st.fieldAt,lastError:st.lastError,modelledLocalEffects:true}},estimateWindAt(lng,lat){if(!st.obs)return null;return{baseSpeedMph:st.obs.speed,windFromDeg:st.obs.dir,sourceDistanceM:st.obs.distance,model:'nearest source observation plus heuristic local flow',confidence:'low for local turbulence'}},estimateRfAt(lng,lat){if(!st.towers.length)return null;let best=null,d=Infinity;for(const t of st.towers){const n=distanceM({lng:+lng,lat:+lat},{lng:t.lng,lat:t.lat});if(n<d){d=n;best=t}}const radius=st.rfMode==='5G'?450:900;return{nearestStructureId:best?.id||null,distanceM:d,nominalRadiusM:radius,insideNominalEnvelope:d<=radius,method:'distance-only planning envelope; not measured radio coverage'}},destroy(){stop();restoreWindTerrain();clearTimeout(st.refreshTimer);map.off?.('moveend',mapMoved);map.off?.('zoomend',mapMoved);root.remove();try{if(map.getLayer(LAYER))map.removeLayer(LAYER)}catch(_){}window.__BP_VOLUMETRIC_FIELDS_V5992__=null}};window.__BP_VOLUMETRIC_FIELDS_V5992__=api;open();return api;
